components.css:
.ds-journey{font-family:var(--font-commercial,Manrope),sans-serif;font-size:16px;line-height:1.65;color:#25153d;}.ds-journey button{font:inherit;cursor:pointer;}.ds-journey button:disabled{cursor:progress;}.ds-journey p{margin:0;}.ds-journey {
  scroll-margin-top: 110px;
}
.ds-header {
  max-width: 1320px;
  margin: auto;
  padding: 24px 48px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  position: relative;
  z-index: 10;
}
.ds-logo {
  width: 190px;
  height: auto;
  object-fit: contain;
}
.ds-desktop-nav,
.ds-header-actions {
  display: flex;
  align-items: center;
  gap: 30px;
}
.ds-desktop-nav a,
.ds-login-link {
  color: var(--ink);
  font-size: 14px;
  font-weight: 600;
  transition: color 180ms ease;
}
.ds-desktop-nav a:hover,
.ds-login-link:hover {
  color: var(--violet);
}
.ds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 22px;
  padding: 17px 23px;
  background: var(--violet);
  color: #fff;
  font-size: 15px;
  font-weight: 700;
  line-height: 1.4;
  border-radius: 8px;
  transition:
    background 180ms ease,
    transform 220ms cubic-bezier(0.16, 1, 0.3, 1);
  min-height: 54px;
}
.ds-button:hover {
  background: #6133b8;
  transform: translateY(-2px);
}
.ds-button svg {
  flex-shrink: 0;
  transition: transform 200ms ease;
}
.ds-button:hover svg {
  transform: translateX(3px);
}
.ds-button-small {
  min-height: 46px;
  padding: 13px 18px;
  font-size: 13px;
  gap: 14px;
}
.ds-button-light {
  background: #fff;
  color: #4e2d91;
}
.ds-button-light:hover {
  background: #ede7fa;
}
.ds-menu-toggle {
  display: none;
  background: transparent;
  border: 0;
  padding: 10px;
  color: var(--ink);
}
.ds-mobile-nav {
  display: none;
}
.ds-skip-link {
  position: absolute;
  top: -90px;
  left: 20px;
  z-index: 50;
  background: #fff;
  padding: 12px 20px;
}
.ds-skip-link:focus {
  top: 12px;
}
.ds-hero {
  max-width: 1320px;
  margin: auto;
  padding: 65px 48px 80px;
  display: grid;
  grid-template-columns: 1.12fr 1fr;
  gap: 58px;
  align-items: center;
}
.ds-hero-copy h1 {
  font-size: clamp(48px, 5.2vw, 72px);
  font-weight: 600;
  line-height: 1.08;
  letter-spacing: -0.038em;
}
.ds-hero-copy h1 span {
  color: var(--violet);
}
.ds-hero-copy > p {
  margin-top: 28px;
  color: var(--muted);
  max-width: 460px;
  font-size: 17px;
  line-height: 1.85;
}
.ds-hero-copy > p strong {
  color: var(--ink);
  font-weight: 650;
}
.ds-hero-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 25px;
  margin-top: 30px;
}
.ds-text-link {
  display: inline-flex;
  gap: 8px;
  align-items: center;
  color: var(--ink);
  font-size: 13px;
  font-weight: 650;
  padding: 12px 0;
}
.ds-hero-note {
  display: flex;
  flex-wrap: wrap;
  gap: 19px;
  margin-top: 22px;
  font-size: 11px;
  color: var(--muted);
}
.ds-hero-note > span {
  display: flex;
  align-items: center;
  gap: 5px;
}
.ds-hero-note svg {
  color: var(--violet);
}
.ds-journey {
  position: relative;
  background: #f0ebfb;
  border-radius: 16px;
  padding: 23px 25px 18px;
}
.ds-journey::before {
  content: "";
  position: absolute;
  width: 86px;
  height: 86px;
  border: 1px solid #cbb8f2;
  border-radius: 18px;
  right: -24px;
  top: -24px;
  z-index: -1;
  transform: rotate(18deg);
}
.ds-journey-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #5a3983;
  font-size: 12px;
  font-weight: 650;
  gap: 10px;
}
.ds-journey-top > span {
  display: flex;
  align-items: center;
  gap: 9px;
}
.ds-status-dot {
  width: 7px;
  height: 7px;
  display: inline-block;
  background: #25855d;
  border-radius: 50%;
  flex-shrink: 0;
}
.ds-sector-switch {
  display: flex;
  gap: 5px;
  margin: 21px 0 14px;
}
.ds-sector-switch button {
  flex: 1;
  border: 0;
  background: transparent;
  border-radius: 6px;
  color: #645972;
  font-size: 12px;
  padding: 9px 5px;
  min-height: 38px;
  transition:
    background 160ms ease,
    color 160ms ease;
}
.ds-sector-switch button[aria-pressed="true"] {
  color: #4e2d91;
  background: #fff;
  font-weight: 750;
}
.ds-demo-window {
  background: #fff;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 12px 28px -17px #4e2d9140;
}
.ds-demo-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 18px 20px;
  border-bottom: 1px solid #ece7f4;
}
.ds-contact-avatar {
  width: 35px;
  height: 35px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #ece6f8;
  color: #6133b8;
  font-size: 12px;
  font-weight: 750;
  flex-shrink: 0;
}
.ds-demo-header strong {
  display: block;
  font-size: 13px;
}
.ds-demo-header small {
  display: block;
  font-size: 10px;
  color: #645972;
}
.ds-demo-header > svg {
  margin-left: auto;
  color: #a384ff;
}
.ds-journey-scene {
  padding: 17px 20px 20px;
  min-height: 340px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  animation: ds-journey-unfold 450ms cubic-bezier(0.16, 1, 0.3, 1) both;
}
@keyframes ds-journey-unfold {
  from {
    clip-path: inset(0 0 18% 0);
    transform: translateY(6px);
  }
  to {
    clip-path: inset(0);
    transform: translateY(0);
  }
}
.ds-demo-date {
  align-self: center;
  font-size: 11px;
  color: #645972;
}
.ds-bubble-incoming,
.ds-bubble-outgoing {
  font-size: 12px;
  line-height: 1.55;
  padding: 9px 12px;
  border-radius: 10px;
  max-width: 88%;
}
.ds-bubble-incoming {
  align-self: flex-start;
  background: #f4f2f7;
  border-bottom-left-radius: 2px;
}
.ds-bubble-outgoing {
  align-self: flex-end;
  background: #eae2fa;
  color: #42276a;
  border-bottom-right-radius: 2px;
}
.ds-message-time {
  display: flex;
  justify-content: flex-end;
  gap: 4px;
  font-size: 10px;
  color: #6d6081;
  margin-top: 3px;
}
.ds-followup-marker {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  text-align: center;
  color: #645972;
  font-size: 11px;
  padding: 3px 0;
}
.ds-followup-marker svg {
  flex-shrink: 0;
}
.ds-journey-activity {
  display: flex;
  align-items: center;
  gap: 10px;
  background: #f8f6fc;
  border-top: 1px solid #ece7f4;
  padding: 14px 18px;
  color: #6133b8;
}
.ds-journey-activity > svg {
  flex-shrink: 0;
}
.ds-journey-activity > svg:last-child {
  margin-left: auto;
}
.ds-journey-activity strong {
  display: block;
  font-size: 11px;
}
.ds-journey-activity span {
  display: block;
  color: #645972;
  font-size: 11px;
  margin-top: 3px;
}
.ds-appointment-result {
  display: flex;
  align-items: center;
  gap: 12px;
  background: #ebf5ee;
  color: #215c3b;
  padding: 16px 14px;
  border-radius: 8px;
  margin-top: auto;
}
.ds-appointment-result > svg {
  flex-shrink: 0;
}
.ds-appointment-result strong,
.ds-appointment-result span,
.ds-appointment-result small {
  display: block;
}
.ds-appointment-result strong {
  font-size: 12px;
}
.ds-appointment-result span {
  font-size: 10px;
  margin-top: 3px;
}
.ds-appointment-result small {
  font-size: 9px;
  margin-top: 3px;
}
.ds-appointment-result > svg:last-child {
  margin-left: auto;
}
.ds-step-switch {
  display: flex;
  gap: 4px;
  margin: 0 0 14px;
}
.ds-step-switch button {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  flex: 1;
  border: 0;
  border-radius: 6px;
  padding: 10px 3px;
  color: #645972;
  background: transparent;
  font-size: 10px;
  min-height: 42px;
  transition: background 180ms ease;
}
.ds-step-switch button > span {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid #cbb8f2;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 9px;
  flex-shrink: 0;
}
.ds-step-switch button[aria-pressed="true"] {
  background: #7c3aed;
  color: #fff;
}
.ds-step-switch button[aria-pressed="true"] > span {
  background: #fff;
  color: #7c3aed;
  border-color: transparent;
}
.ds-demo-caption {
  text-align: center;
  margin-top: 12px !important;
  font-size: 11px;
  color: #645972;
}
.ds-journey button:focus-visible{outline:3px solid #915fff;outline-offset:5px;}@media(max-width:1100px){.ds-journey{padding-inline:18px;}}@media(max-width:520px){.ds-journey{padding:18px 14px 16px;}.ds-journey-top{font-size:10px;}.ds-sector-switch{margin-top:15px;}.ds-demo-header{padding:14px;}.ds-journey-scene{padding:14px;min-height:325px;}.ds-step-switch button{font-size:9px;gap:4px;}}@media(prefers-reduced-motion:reduce){.ds-journey-scene{animation:none;}.ds-sector-switch button,.ds-step-switch button{transition:none;}}@media(forced-colors:active){.ds-journey button:focus-visible{outline:2px solid Highlight!important;outline-offset:2px!important;}}

.ds-report-preview h3,.ds-report-preview p{margin:0;}.ds-report-preview {
  background: #f8f6fd;
  border: 1px solid var(--line,#e6e0ef);
  border-radius: 12px;
  padding: 24px;
}
.ds-report-controls {
  display: flex;
  gap: 8px;
  padding-bottom: 22px;
}
.ds-report-controls button {
  color: var(--muted,#645972);
  border: 0;
  background: transparent;
  padding: 9px 18px;
  border-radius: 8px;
  font-size: 13px;
}
.ds-report-controls button[aria-pressed="true"] {
  background: var(--violet,#7c3aed);
  color: white;
}
.ds-report-data h3 {
  font-size: 18px;
  font-weight: 650;
}
.ds-report-data > p {
  font-size: 12px;
  color: var(--muted,#645972);
  margin-top: 6px;
}
.ds-report-data dl {
  margin: 22px 0;
}
.ds-report-data dl > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  border-top: 1px solid var(--line,#e6e0ef);
  padding: 16px 0;
}
.ds-report-data dt {
  font-size: 13px;
}
.ds-report-data dd {
  margin: 0;
  text-align: right;
  font-size: 22px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.ds-report-data dd span {
  display: block;
  font-size: 11px;
  font-weight: 400;
  color: var(--muted,#645972);
}
.ds-report-delivery {
  display: flex;
  align-items: center;
  gap: 9px;
  color: var(--muted,#645972);
  font-size: 11px;
}
.ds-report-delivery svg {
  flex-shrink: 0;
  color: var(--violet,#7c3aed);
}
@media (max-width: 820px) {

}
@media (max-width: 520px) {
  .ds-report-preview {
    padding: 20px;
  }
}
.ds-report-preview{font-family:var(--font-commercial,Manrope),sans-serif;color:var(--ink,#25153d);line-height:1.65;}.ds-report-controls button{font-family:inherit;line-height:inherit;cursor:pointer;}.ds-report-controls button:focus-visible{outline:3px solid #915fff;outline-offset:5px;}.ds-report-caption{
  font-size: 11px;
  color: #645972;
  margin-top: 13px !important;
  text-align: center;
}@media(forced-colors:active){.ds-report-controls button:focus-visible{outline:2px solid Highlight!important;outline-offset:2px!important;}}.ds-report-controls button:disabled{cursor:progress;}

.ds-commercial-pattern{font-family:var(--font-commercial,Manrope),sans-serif;color:var(--ink,#25153d);line-height:1.65;}.ds-commercial-pattern h3,.ds-commercial-pattern h4,.ds-commercial-pattern p{margin:0;}.ds-commercial-pattern button{font:inherit;cursor:pointer;}.ds-commercial-pattern button:disabled{cursor:progress;}.ds-commercial-pattern button:focus-visible{outline:3px solid #915fff;outline-offset:5px;}@media(forced-colors:active){.ds-commercial-pattern button:focus-visible{outline:2px solid Highlight!important;outline-offset:2px!important;}}.ds-opportunity-tabs {
  display: flex;
  gap: 26px;
  border-bottom: 1px solid var(--line,#e6e0ef);
}
.ds-opportunity-tabs button {
  padding: 15px 0;
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--muted,#645972);
  font-size: 14px;
  text-align: left;
}
.ds-opportunity-tabs button[aria-pressed="true"] {
  color: var(--violet,#7c3aed);
  border-bottom-color: var(--violet,#7c3aed);
  font-weight: 750;
}
.ds-opportunity-comparison {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 48px;
  padding-top: 34px;
}
.ds-opportunity-risk {
  padding: 28px 0;
}
.ds-opportunity-comparison h3 {
  font-size: 25px;
  line-height: 1.35;
  font-weight: 650;
  letter-spacing: -0.025em;
  margin-top: 0;
}
.ds-opportunity-risk p {
  font-size: 14px;
  color: var(--muted,#645972);
  margin-top: 15px;
  max-width: 42ch;
}
.ds-risk-conclusion {
  display: block;
  font-size: 12px;
  color: var(--muted,#645972);
  margin-top: 26px;
}
.ds-opportunity-response {
  padding: 28px 32px;
  background: var(--lavender,#ede7fa);
  border-radius: 12px;
}
.ds-opportunity-response ol {
  list-style: none;
  padding: 0;
  margin: 22px 0;
  display: grid;
  gap: 11px;
}
.ds-opportunity-response li {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  font-size: 13px;
}
.ds-opportunity-response li svg {
  flex-shrink: 0;
  color: #6133b8;
  margin-top: 3px;
}
.ds-opportunity-outcome {
  display: flex;
  align-items: center;
  gap: 9px;
  padding-top: 18px;
  border-top: 1px solid #cbb8f2;
  color: #4e2d91;
  font-size: 13px;
  font-weight: 750;
}
.ds-opportunity-outcome svg {
  flex-shrink: 0;
}
.ds-scenario-note {
  color: var(--muted,#645972);
  font-size: 11px;
  margin-top: 18px !important;
}
@media(max-width:820px){.ds-opportunity-comparison{gap:26px;}.ds-opportunity-response{padding:24px;}.ds-opportunity-comparison h3{font-size:22px;}}@media(max-width:520px){.ds-opportunity-tabs{gap:12px;}.ds-opportunity-tabs button{flex:1;font-size:11px;line-height:1.6;padding-block:12px;}.ds-opportunity-comparison{grid-template-columns:1fr;gap:18px;padding-top:22px;}.ds-opportunity-risk{padding:0;}.ds-opportunity-comparison h3{font-size:23px;}.ds-opportunity-risk p{font-size:13px;}.ds-risk-conclusion{margin-top:15px;}.ds-opportunity-response{padding:22px;}.ds-scenario-note{font-size:10px;}}

.ds-commercial-pattern{font-family:var(--font-commercial,Manrope),sans-serif;color:var(--ink,#25153d);line-height:1.65;}.ds-commercial-pattern h3,.ds-commercial-pattern h4,.ds-commercial-pattern p{margin:0;}.ds-commercial-pattern button{font:inherit;cursor:pointer;}.ds-commercial-pattern button:disabled{cursor:progress;}.ds-commercial-pattern button:focus-visible{outline:3px solid #915fff;outline-offset:5px;}@media(forced-colors:active){.ds-commercial-pattern button:focus-visible{outline:2px solid Highlight!important;outline-offset:2px!important;}}.ds-operation-benefits {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 35px;
  align-items: start;
  margin-bottom: 24px;
}
.ds-operation-benefits h3 {
  color: #6133b8;
  font-size: 23px;
  font-weight: 650;
  line-height: 1.4;
  letter-spacing: -0.025em;
}
.ds-operation-benefits p {
  font-size: 14px;
  color: var(--muted,#645972);
}
.ds-operation-result {
  display: flex;
  align-items: center;
  gap: 9px;
  background: #f5f1fc;
  color: #6133b8;
  padding: 16px 25px;
  font-size: 12px;
  font-weight: 650;
  border-top: 1px solid var(--line,#e6e0ef);
}
.ds-operation-result svg {
  flex-shrink: 0;
}
.ds-operation-preview {
  border: 1px solid #ded6ec;
  border-radius: 12px;
  overflow: hidden;
}
.ds-preview-body {
  display: flex;
  min-height: 315px;
}
.ds-preview-sidebar {
  width: 185px;
  flex-shrink: 0;
  padding: 26px 15px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  border-right: 1px solid #e6e0ef;
}
.ds-preview-sidebar button {
  display: flex;
  gap: 10px;
  align-items: center;
  border: 0;
  background: transparent;
  border-radius: 6px;
  color: #645972;
  padding: 12px;
  font-size: 12px;
  text-align: left;
}
.ds-preview-sidebar button[aria-pressed="true"] {
  background: #eee7fc;
  color: #6133b8;
  font-weight: 750;
}
.ds-preview-content {
  padding: 28px;
  width: 100%;
  min-width: 0;
}
.ds-preview-title {
  display: flex;
  gap: 10px;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 24px;
}
.ds-preview-title h3 {
  font-size: 15px;
  font-weight: 700;
}
.ds-preview-title > span {
  color: #645972;
  font-size: 9px;
  white-space: nowrap;
}
.ds-pipeline-preview {
