}
.ds-pipeline-preview > div {
  background: #f6f3fa;
  padding: 14px;
  border-radius: 8px;
}
.ds-pipeline-preview h4 {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10px;
  font-weight: 650;
}
.ds-pipeline-preview h4 span {
  width: 6px;
  height: 6px;
  background: #7c3aed;
  border-radius: 50%;
}
.ds-pipeline-preview article {
  margin-top: 15px;
  padding: 14px;
  background: #fff;
  border-radius: 6px;
  font-size: 10px;
}
.ds-pipeline-preview article p {
  font-size: 9px;
  margin-top: 5px;
  color: #645972;
}
.ds-pipeline-preview article > span {
  display: flex;
  align-items: center;
  gap: 5px;
  margin-top: 22px;
  font-size: 8px;
  color: #6133b8;
}@media(max-width:1100px){.ds-preview-sidebar{width:160px;}.ds-preview-content{padding:23px;}}@media(max-width:820px){.ds-preview-body{display:block;}.ds-preview-sidebar{width:100%;flex-direction:row;padding:12px 15px;border-right:0;border-bottom:1px solid #e6e0ef;flex-wrap:wrap;}.ds-preview-sidebar button{flex:1;justify-content:center;}.ds-preview-content{min-height:275px;}}@media(max-width:520px){.ds-operation-benefits{grid-template-columns:1fr;gap:10px;}.ds-operation-benefits h3{font-size:22px;}.ds-operation-benefits p{font-size:13px;}.ds-operation-result{padding:15px;font-size:11px;}.ds-preview-sidebar{padding:8px;gap:4px;display:grid;grid-template-columns:repeat(3,1fr);}.ds-preview-sidebar button{font-size:10px;gap:5px;padding:10px 5px;}.ds-preview-content{padding:18px 14px;min-height:390px;}.ds-preview-title{flex-direction:column;gap:5px;margin-bottom:15px;}.ds-preview-title h3{font-size:13px;}.ds-pipeline-preview{grid-template-columns:1fr;gap:9px;}.ds-pipeline-preview>div{padding:11px;}.ds-pipeline-preview article{margin-top:8px;padding:11px;}.ds-pipeline-preview article>span{margin-top:9px;}}

.ds-business-photo{font-family:var(--font-commercial,Manrope),sans-serif;color:#25153d;line-height:1.65;}.ds-photo-chat p{margin:0;}.ds-business-photo {
  position: relative;
  min-width: 0;
  height: 470px;
  border-radius: 12px;
  overflow: hidden;
}
.ds-photo-chat {
  position: absolute;
  right: 22px;
  bottom: 55px;
  width: 270px;
  background: #fff;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 16px 40px -16px #25153d66;
}
.ds-photo-chat-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  background: #fff;
}
.ds-photo-chat-header > svg {
  color: var(--support-green,#146b4d);
  flex-shrink: 0;
}
.ds-photo-chat-header strong {
  display: block;
  font-size: 12px;
}
.ds-photo-chat-header span {
  display: block;
  font-size: 10px;
  color: var(--muted,#645972);
}
.ds-photo-chat-body {
  display: grid;
  gap: 10px;
  padding: 15px;
  background: #f1f5ef;
}
.ds-photo-chat-body p {
  padding: 9px 11px;
  font-size: 11px;
  line-height: 1.6;
  max-width: 93%;
}
.ds-photo-chat-body p span {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 4px;
  font-size: 9px;
  color: #496457;
  margin-top: 3px;
}
.ds-photo-incoming {
  background: white;
  border-radius: 8px 8px 8px 2px;
}
.ds-photo-outgoing {
  background: #dff0e6;
  justify-self: end;
  border-radius: 8px 8px 2px 8px;
}
.ds-photo-outcome {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 13px 15px;
  color: var(--support-blue,#215da8);
}
.ds-photo-outcome > svg {
  flex-shrink: 0;
}
.ds-photo-outcome strong {
  display: block;
  font-size: 10px;
}
.ds-photo-outcome span {
  display: block;
  font-size: 9px;
}
.ds-business-photo[data-entered="true"] .ds-photo-chat {
  animation: ds-photo-conversation-arrives 650ms cubic-bezier(0.16, 1, 0.3, 1) both;
}
.ds-business-photo[data-entered="true"] .ds-photo-outcome {
  animation: ds-photo-conversation-arrives 650ms 160ms cubic-bezier(0.16, 1, 0.3, 1) both;
}
@keyframes ds-photo-conversation-arrives {
  from {
    transform: translateY(16px);
    clip-path: inset(0 0 12% 0 round 12px);
  }
  to {
    transform: translateY(0);
    clip-path: inset(0 0 0 0 round 12px);
  }
}
@media(max-width:520px){.ds-business-photo{height:auto;overflow:visible;}.ds-photo-chat{position:relative;margin:0 12px 0 auto;right:auto;bottom:auto;width:calc(100% - 30px);max-width:285px;}.ds-photo-chat-body p{font-size:12px;}.ds-photo-chat-header strong{font-size:13px;}.ds-photo-outcome strong{font-size:11px;}}@media(prefers-reduced-motion:reduce){.ds-business-photo .ds-photo-chat,.ds-business-photo .ds-photo-outcome{animation:none!important;}}
